// MTP / speculative decoding golden test (dsv4_ext).
//
// Fixtures (generated by tools/tiny_model.py, which also writes the numpy references):
//   python3 tools/tiny_model.py build-out/tiny_model
//   ./build-out/test_mtp --model build-out/tiny_model/tiny.gguf [--refdir build-out/tiny_model]
//
// The tiny model has 4 main layers + ONE extra MTP layer (ratio 8: the compressor path, no indexer) and the
// DeepSeek-V3-style fusion tensors mtp.enorm/hnorm/eh_proj. References written by numpy (float64):
//   ref_logits.bin          [26][V]    main-model logits at every prompt position
//   tokens.txt              26 comma-separated prompt token ids
//   ref_mtp_hidden.bin      [HC*DIM]   main hidden state after the last prompt token (feeds draft step 0)
//   ref_mtp_draft_logits    [4][V]     MTP logits of each chained greedy draft step
//   ref_mtp_draft_toks.txt  "a,b,c,d"  the four greedy drafts
//   ref_verify_logits       [4][V]     main-model logits at every verify position (over the draft chain)
//
// What is checked:
//  T0 load        exactly one MTP layer is exposed; prefill runs it at every position.
//  T1 draft parity greedy spec_step drafts == numpy's chained MTP argmaxes; next_logits == numpy verify logits.
//  T2 state       after a speculative step the cache holds prompt + accepted drafts (correction/bonus NOT in it).
//  T3 parity      greedy decoding with --spec and without produces IDENTICAL token streams (acceptance + rollback).
//  T4 determinism same seed -> identical sampled stream; per-round emission is within [1, N+1].
//  T5 checkpoint  a KV checkpoint taken mid-speculation restores the FULL state (main + MTP): continuation matches.

#include "dsv4/model.hpp"
#include "dsv4/sampler.hpp"

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <string>
#include <vector>

using namespace dsv4;

static int g_fail = 0;
#define CHECK(cond) do { if (!(cond)) { std::printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); ++g_fail; } else std::printf("ok   %s\n", #cond); } while (0)

static bool near(const std::vector<float>& a, const float* b, int n, double tol = 2e-3) {
    if ((int) a.size() != n) return false;
    for (int i = 0; i < n; ++i) if (std::fabs((double) a[i] - (double) b[i]) > tol) return false;
    return true;
}
static int argmax(const std::vector<float>& v) { int m = 0; for (size_t i = 1; i < v.size(); ++i) if (v[i] > v[m]) m = (int) i; return m; }

static bool read_f32(const std::string& path, std::vector<float>& out) {
    std::ifstream f(path, std::ios::binary);
    if (!f) return false;
    f.seekg(0, std::ios::end); const long n = f.tellg(); f.seekg(0, std::ios::beg);
    out.resize((size_t)(n / 4));
    return (bool) f.read(reinterpret_cast<char*>(out.data()), n);
}
static bool read_ids(const std::string& path, std::vector<int>& out) {
    std::ifstream f(path); if (!f) return false;
    std::string t; while (std::getline(f, t, ',')) if (!t.empty()) out.push_back(std::atoi(t.c_str()));
    return !out.empty();
}

static RunOpts base_opts(int spec_n) {
    RunOpts o;
    o.ctx = 64; o.gpu = false; o.qat_sim = false; o.verbose = false; o.prefill_chunk = 1;   // token-by-token, like numpy
    o.spec_n = spec_n;
    return o;
}

int main(int argc, char** argv) {
    std::string model = "build-out/tiny_model/tiny.gguf", refdir = "build-out/tiny_model";
    for (int i = 1; i + 1 < argc; ++i) { if (!std::strcmp(argv[i], "--model")) model = argv[++i]; else if (!std::strcmp(argv[i], "--refdir")) refdir = argv[++i]; }

    setvbuf(stdout, nullptr, _IONBF, 0);
    const int V = 40, HC_DIM = 256, NPROMPT = 26, NDRAFT = 4;   // tiny_model.py constants (kept in sync by hand)

    std::vector<int> toks; std::vector<float> ref_logits, ref_hidden, ref_draft_lg, ref_verify;
    std::vector<int> ref_drafts;
    if (!read_ids(refdir + "/tokens.txt", toks) || !read_f32(refdir + "/ref_logits.bin", ref_logits) ||
        !read_f32(refdir + "/ref_mtp_hidden.bin", ref_hidden) || !read_f32(refdir + "/ref_mtp_draft_logits.bin", ref_draft_lg) ||
        !read_ids(refdir + "/ref_mtp_draft_toks.txt", ref_drafts) || !read_f32(refdir + "/ref_verify_logits.bin", ref_verify)) {
        std::printf("FAIL cannot read fixtures from %s (run: python3 tools/tiny_model.py %s)\n", refdir.c_str(), refdir.c_str());
        return 1;
    }
    CHECK((int) toks.size() == NPROMPT && (int) ref_drafts.size() == NDRAFT);

    // ------------------------------------------------------------------ T0: load, MTP layer exposed
    Model m; std::string err;
    if (!m.load({model}, base_opts(NDRAFT), err)) { std::printf("FAIL load: %s\n", err.c_str()); return 1; }
    CHECK(m.mtp_layers() == 1);

    // ------------------------------------------------------------------ T1: draft parity against numpy
    m.reset();
    std::vector<float> cur;
    for (int i = 0; i < NPROMPT; ++i) { std::vector<float> lg; m.forward(toks[(size_t) i], i, &lg); m.end_token(); if ((size_t)(i + 1) == toks.size()) cur = lg; }
    CHECK(near(cur, ref_logits.data() + (size_t)(NPROMPT - 1) * V, V));                 // main logits at the last prompt position
    { const std::vector<float> hid = m.last_hidden_state(); CHECK((int) hid.size() == HC_DIM && near(hid, ref_hidden.data(), HC_DIM)); }

    SampleOpts so;   // greedy (temperature 0): no RNG, deterministic acceptance
    Sampler smp(so);
    std::vector<float> nxt;
    const std::vector<int> got = m.spec_step(cur.data(), so, &smp, &nxt);

    // numpy's drafts are the argmaxes of ref_draft_lg; C++ must have produced exactly those.
    for (int j = 0; j < NDRAFT; ++j) CHECK(ref_drafts[(size_t) j] == argmax(std::vector<float>(ref_draft_lg.begin() + (size_t) j * V, ref_draft_lg.begin() + (size_t)(j + 1) * V)));
    // greedy acceptance over numpy's verify logits: the expected emitted sequence.
    int acc = 0;
    if (argmax(cur) == ref_drafts[0]) acc = 1;
    for (int j = 1; j < NDRAFT && acc > 0; ++j) if (argmax(std::vector<float>(ref_verify.begin() + (size_t)(j - 1) * V, ref_verify.begin() + (size_t) j * V)) == ref_drafts[(size_t) j]) ++acc;
    // `got` holds ONLY the accepted drafts - every token in it is already in the KV cache. The bonus/correction
    // token is NOT emitted here: its distribution is exactly nxt, and it materialises as the first emission of
    // the next round (accepted by verify, or sampled + forwarded when nothing was accepted).
    // When nothing was accepted spec_step emitted the correction token itself (argmax of `cur`), so it is part of
    // the expected output; otherwise only the accepted drafts are.
    std::vector<int> corr; std::vector<float> corr_lg;
    if (acc == 0) CHECK(read_ids(refdir + "/ref_corr_tok.txt", corr) && read_f32(refdir + "/ref_correction_logits.bin", corr_lg));
    std::vector<int> expect;
    for (int j = 0; j < acc; ++j) expect.push_back(ref_drafts[(size_t) j]);
    if (acc == 0 && !corr.empty()) expect.push_back(corr[0]);
    CHECK((int) got.size() == (int) expect.size());
    for (size_t i = 0; i < std::min(got.size(), expect.size()); ++i) CHECK(got[i] == expect[i]);

    // next_logits: the verify distribution of the position right after the accepted span...
    const int hi = acc > 0 ? acc - 1 : -1;
    if (hi >= 0) {
        CHECK(near(nxt, ref_verify.data() + (size_t) hi * V, V));
    } else {
        // ...or, when nothing was accepted, the logits of the correction token that spec_step processed itself.
        CHECK((int) got.size() == 1 && (int) got[0] == corr[0]);
        CHECK(near(nxt, corr_lg.data(), V));
    }

    // ------------------------------------------------------------------ T2: cache state after the speculative step
    // Accepted drafts are in; when nothing was accepted spec_step forwarded the correction token itself.
    CHECK((int) m.cached_tokens().size() == NPROMPT + (acc > 0 ? acc : 1));

    // ------------------------------------------------------------------ T3: greedy parity, spec vs plain
    {
        Model A, B;
        if (!A.load({model}, base_opts(0), err)) { std::printf("FAIL load A\n"); return 1; }
        if (!B.load({model}, base_opts(NDRAFT), err)) { std::printf("FAIL load B\n"); return 1; }
        const int G = 12;
        // A: plain greedy decoding.
        A.reset(); std::vector<int> ta, tb;
        for (int i = 0; i < NPROMPT; ++i) { std::vector<float> lg; A.forward(toks[(size_t) i], i, &lg); A.end_token(); if (i + 1 == NPROMPT) { int t = argmax(lg); ta.push_back(t); } }
        for (int g = 0; g < G - 1; ++g) { std::vector<float> lg; A.forward(ta[(size_t) g], NPROMPT + g, &lg); A.end_token(); ta.push_back(argmax(lg)); }
        // B: speculative decoding.
        B.reset(); std::vector<float> blg;
        for (int i = 0; i < NPROMPT; ++i) { std::vector<float> lg; B.forward(toks[(size_t) i], i, &lg); B.end_token(); if (i + 1 == NPROMPT) blg = lg; }
        Sampler bs(SampleOpts{});
        while ((int) tb.size() < G && !blg.empty()) {
            std::vector<float> bnx;
            const std::vector<int> r = B.spec_step(blg.data(), SampleOpts{}, &bs, &bnx);
            if (r.empty()) break;
            for (int t : r) tb.push_back(t);
            blg = std::move(bnx);
        }
        CHECK((int) ta.size() == G && (int) tb.size() == G);
        bool same = true; for (int i = 0; i < G; ++i) if (ta[(size_t) i] != tb[(size_t) i]) { same = false; std::printf("       first diff at %d: plain=%d spec=%d\n", i, ta[(size_t) i], tb[(size_t) i]); }
        CHECK(same);
    }

    // ------------------------------------------------------------------ T4: sampled determinism + emission bounds
    {
        auto run_sampled = [&](uint64_t seed) {
            Model M; std::string e2;
            if (!M.load({model}, base_opts(NDRAFT), e2)) return std::vector<int>();
            M.reset();
            SampleOpts s2; s2.temperature = 0.8f; s2.top_p = 0.9f; s2.seed = seed;
            Sampler sm(s2);
            std::vector<float> lg;
            for (int i = 0; i < NPROMPT; ++i) { std::vector<float> l; M.forward(toks[(size_t) i], i, &l); M.end_token(); if (i + 1 == NPROMPT) lg = l; }
            std::vector<int> out; bool bound_ok = true;
            for (int r = 0; r < 6 && !lg.empty() && (int) out.size() < 24; ++r) {
                std::vector<float> nx;
                const std::vector<int> g = M.spec_step(lg.data(), s2, &sm, &nx);
                if (g.empty()) break;
                if ((int) g.size() < 1 || (int) g.size() > NDRAFT + 1) bound_ok = false;
                for (int t : g) out.push_back(t);
                lg = std::move(nx);
            }
            CHECK(bound_ok);   // every round emits between 1 and N+1 tokens
            return out;
        };
        const std::vector<int> a = run_sampled(123), b = run_sampled(123), c = run_sampled(456);
        CHECK(!a.empty());
        bool same = true; for (size_t i = 0; i < a.size() && i < b.size(); ++i) if (a[i] != b[i]) same = false;
        CHECK(same);   // same seed -> identical stream
    }

    // ------------------------------------------------------------------ T5: checkpoint across speculation
    {
        Model B, C; std::string e2;
        if (!B.load({model}, base_opts(NDRAFT), e2)) { std::printf("FAIL load B\n"); return 1; }
        B.reset();
        SampleOpts so2;   // greedy for a deterministic continuation
        Sampler sm(SampleOpts{});
        std::vector<float> lg;
        for (int i = 0; i < NPROMPT; ++i) { std::vector<float> l; B.forward(toks[(size_t) i], i, &l); B.end_token(); if (i + 1 == NPROMPT) lg = l; }
        std::vector<int> before;
        for (int r = 0; r < 3 && !lg.empty(); ++r) { std::vector<float> nx; const std::vector<int> g = B.spec_step(lg.data(), so2, &sm, &nx); if (g.empty()) break; for (int t : g) before.push_back(t); lg = std::move(nx); }
        CHECK(!before.empty());
        const std::string ck = "/tmp/dsv4_mtp_ck.bin"; std::remove(ck.c_str());
        CHECK(B.save_kv(ck, err));

        if (!C.load({model}, base_opts(NDRAFT), e2)) { std::printf("FAIL load C\n"); return 1; }
        CHECK(C.load_kv(ck, err));
        const std::vector<int> hist = B.cached_tokens();   // [prompt + before]
        CHECK((int) C.cached_tokens().size() == (int) hist.size());

        // C continues the restored conversation exactly like production does: pass the whole history as a "prompt",
        // reuse everything but the last token, and re-forward that one for the continuation logits. The recompute is
        // idempotent (deterministic math overwrites its own ring/compressor rows with identical values).
        const int k = C.reuse_prefix(hist);
        CHECK(k == (int) hist.size() - 1);
        std::vector<float> lgC;
        C.forward(hist[(size_t)(hist.size() - 1)], k, &lgC);

        // continue both for three more speculative rounds: the streams must match token for token.
        auto cont = [&](Model& M, std::vector<float>& l2) {
            Sampler sm2(SampleOpts{});
            std::vector<int> out;
            for (int r = 0; r < 3 && !l2.empty(); ++r) { std::vector<float> nx; const std::vector<int> g = M.spec_step(l2.data(), so2, &sm2, &nx); if (g.empty()) break; for (int t : g) out.push_back(t); l2 = std::move(nx); }
            return out;
        };
        std::vector<float> lgB = lg;   // B's current distribution
        const std::vector<int> rb = cont(B, lgB), rc = cont(C, lgC);
        CHECK((int) rb.size() == (int) rc.size());
        for (size_t i = 0; i < std::min(rb.size(), rc.size()); ++i) CHECK(rb[i] == rc[i]);
    }

    // ------------------------------------------------------------------ T6: batched verify == sequential verify
    {
        // The production serve loop runs with a chunked prefill, so spec_step's verify takes forward_chunk_all's
        // BATCHED branch (T <= pf_cap). It must yield the same greedy stream as the token-by-token fallback that
        // T3 exercised.
        Model A, B; std::string e2;
        RunOpts o6 = base_opts(NDRAFT); o6.prefill_chunk = 8;   // 4 drafts <= pf_cap: batched verify
        if (!A.load({model}, base_opts(0), e2)) { std::printf("FAIL load A6\n"); return 1; }
        if (!B.load({model}, o6, e2)) { std::printf("FAIL load B6\n"); return 1; }
        const int G = 12;
        A.reset(); std::vector<int> ta, tb;
        for (int i = 0; i < NPROMPT; ++i) { std::vector<float> lg; A.forward(toks[(size_t) i], i, &lg); A.end_token(); if (i + 1 == NPROMPT) { int t = argmax(lg); ta.push_back(t); } }
        for (int g = 0; g < G - 1; ++g) { std::vector<float> lg; A.forward(ta[(size_t) g], NPROMPT + g, &lg); A.end_token(); ta.push_back(argmax(lg)); }
        B.reset(); std::vector<float> blg;
        for (int i = 0; i < NPROMPT; ++i) { std::vector<float> lg; B.forward(toks[(size_t) i], i, &lg); B.end_token(); if (i + 1 == NPROMPT) blg = lg; }
        Sampler bs(SampleOpts{});
        while ((int) tb.size() < G && !blg.empty()) {
            std::vector<float> bnx;
            const std::vector<int> r = B.spec_step(blg.data(), SampleOpts{}, &bs, &bnx);
            if (r.empty()) break;
            for (int t : r) tb.push_back(t);
            blg = std::move(bnx);
        }
        CHECK((int) ta.size() == G && (int) tb.size() == G);
        bool same6 = true;
        for (int i = 0; i < G; ++i) if (ta[(size_t) i] != tb[(size_t) i]) { same6 = false; std::printf("       first diff at %d: plain=%d spec-batched=%d\n", i, ta[(size_t) i], tb[(size_t) i]); }
        CHECK(same6);
    }

    if (g_fail) { std::printf("MTP TEST: %d FAILURES\n", g_fail); return 1; }
    std::printf("MTP TEST: all checks passed\n");
    return 0;
}
